-- CrowSpace Phase 3 security and realtime policies
-- Requires 20261110_crowspace_phase3_communities_events.sql first.
create policy "Discover public CrowSpace communities" on public.crowspace_communities for select to authenticated using(privacy='public' or owner_id=(select auth.uid()) or exists(select 1 from public.crowspace_community_members m where m.community_id=id and m.user_id=(select auth.uid()) and m.status='active'));
create policy "Create own CrowSpace communities" on public.crowspace_communities for insert to authenticated with check(owner_id=(select auth.uid()));
create policy "Owners update communities" on public.crowspace_communities for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create policy "Owners delete communities" on public.crowspace_communities for delete to authenticated using(owner_id=(select auth.uid()));
create policy "Read own or owned community memberships" on public.crowspace_community_members for select to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.crowspace_communities c where c.id=community_id and c.owner_id=(select auth.uid())));
create policy "Join public communities or accept invitation or owner adds members" on public.crowspace_community_members for insert to authenticated with check(
 (crowspace_community_members.user_id=(select auth.uid()) and crowspace_community_members.role='member' and (
 (crowspace_community_members.status='active' and exists(select 1 from public.crowspace_communities c where c.id=community_id and c.privacy='public' and c.join_policy='open'))
 or (crowspace_community_members.status='pending' and exists(select 1 from public.crowspace_communities c where c.id=community_id and c.privacy='public' and c.join_policy='request'))
 or exists(select 1 from public.crowspace_community_invitations i where i.community_id=crowspace_community_members.community_id and i.invitee_id=(select auth.uid()) and i.status='accepted')
 )) or exists(select 1 from public.crowspace_communities c where c.id=community_id and c.owner_id=(select auth.uid())));
create policy "Leave community or owner removes members" on public.crowspace_community_members for delete to authenticated using(user_id=(select auth.uid()) or exists(select 1 from public.crowspace_communities c where c.id=community_id and c.owner_id=(select auth.uid())));
create policy "Owners manage membership" on public.crowspace_community_members for update to authenticated using(exists(select 1 from public.crowspace_communities c where c.id=community_id and c.owner_id=(select auth.uid()))) with check(exists(select 1 from public.crowspace_communities c where c.id=community_id and c.owner_id=(select auth.uid())));
create policy "Read discussions as active member" on public.crowspace_community_posts for select to authenticated using(exists(select 1 from public.crowspace_community_members m where m.community_id=community_id and m.user_id=(select auth.uid()) and m.status='active'));
create policy "Active members publish discussions" on public.crowspace_community_posts for insert to authenticated with check(author_id=(select auth.uid()) and exists(select 1 from public.crowspace_community_members m where m.community_id=community_id and m.user_id=(select auth.uid()) and m.status='active'));
create policy "Authors edit discussions" on public.crowspace_community_posts for update to authenticated using(author_id=(select auth.uid())) with check(author_id=(select auth.uid()));
create policy "Authors or owners delete discussions" on public.crowspace_community_posts for delete to authenticated using(author_id=(select auth.uid()) or exists(select 1 from public.crowspace_communities c where c.id=community_id and c.owner_id=(select auth.uid())));
create policy "Read comments in accessible discussions" on public.crowspace_community_comments for select to authenticated using(exists(select 1 from public.crowspace_community_posts p where p.id=post_id));
create policy "Active members comment on discussions" on public.crowspace_community_comments for insert to authenticated with check(author_id=(select auth.uid()) and exists(select 1 from public.crowspace_community_posts p join public.crowspace_community_members m on m.community_id=p.community_id where p.id=post_id and m.user_id=(select auth.uid()) and m.status='active'));
create policy "Authors delete own community comments" on public.crowspace_community_comments for delete to authenticated using(author_id=(select auth.uid()));
create policy "Discover accessible events" on public.crowspace_events for select to authenticated using(creator_id=(select auth.uid()) or visibility='public' or (visibility='community' and exists(select 1 from public.crowspace_community_members m where m.community_id=crowspace_events.community_id and m.user_id=(select auth.uid()) and m.status='active')) or exists(select 1 from public.crowspace_event_invitations i where i.event_id=id and i.invitee_id=(select auth.uid())));
create policy "Create events as creator" on public.crowspace_events for insert to authenticated with check(creator_id=(select auth.uid()) and (community_id is null or exists(select 1 from public.crowspace_community_members m where m.community_id=crowspace_events.community_id and m.user_id=(select auth.uid()) and m.status='active')));
create policy "Creators update events" on public.crowspace_events for update to authenticated using(creator_id=(select auth.uid())) with check(creator_id=(select auth.uid()));
create policy "Creators delete events" on public.crowspace_events for delete to authenticated using(creator_id=(select auth.uid()));
create policy "Read community invitations" on public.crowspace_community_invitations for select to authenticated using(invitee_id=(select auth.uid()) or inviter_id=(select auth.uid()));
create policy "Community owners invite members" on public.crowspace_community_invitations for insert to authenticated with check(inviter_id=(select auth.uid()) and exists(select 1 from public.crowspace_communities c where c.id=community_id and c.owner_id=(select auth.uid())));
create policy "Invitees respond to community invitations" on public.crowspace_community_invitations for update to authenticated using(invitee_id=(select auth.uid())) with check(invitee_id=(select auth.uid()));
create policy "Inviters revoke community invitations" on public.crowspace_community_invitations for delete to authenticated using(inviter_id=(select auth.uid()));
create policy "Read event invitations" on public.crowspace_event_invitations for select to authenticated using(invitee_id=(select auth.uid()) or inviter_id=(select auth.uid()) or exists(select 1 from public.crowspace_events e where e.id=event_id and e.creator_id=(select auth.uid())));
create policy "Event creators send invitations" on public.crowspace_event_invitations for insert to authenticated with check(inviter_id=(select auth.uid()) and exists(select 1 from public.crowspace_events e where e.id=event_id and e.creator_id=(select auth.uid())));
create policy "Invitees respond to event invitations" on public.crowspace_event_invitations for update to authenticated using(invitee_id=(select auth.uid())) with check(invitee_id=(select auth.uid()));
create policy "Inviters revoke event invitations" on public.crowspace_event_invitations for delete to authenticated using(inviter_id=(select auth.uid()));
create policy "Read RSVPs for accessible events" on public.crowspace_event_rsvps for select to authenticated using(exists(select 1 from public.crowspace_events e where e.id=event_id));
create policy "Manage own RSVPs" on public.crowspace_event_rsvps for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.crowspace_events e where e.id=event_id));
create policy "Update own RSVPs" on public.crowspace_event_rsvps for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
create policy "Delete own RSVPs" on public.crowspace_event_rsvps for delete to authenticated using(user_id=(select auth.uid()));
do $$ declare t text; begin foreach t in array array['crowspace_communities','crowspace_community_members','crowspace_community_posts','crowspace_community_comments','crowspace_community_invitations','crowspace_events','crowspace_event_invitations','crowspace_event_rsvps'] loop if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=t) then execute format('alter publication supabase_realtime add table public.%I',t); end if; end loop; end $$;
